create or replace function public.cleanup_gateway_e2e_orphan_traces() returns integer language plpgsql security definer set search_path=public as $$ declare v_count integer; begin delete from public.gateway_orchestration_traces where transaction_id is null and idempotency_key like 'e2e-trace-%'; get diagnostics v_count = row_count; return v_count; end; $$; revoke all on function public.cleanup_gateway_e2e_orphan_traces() from public,anon,authenticated; grant execute on function public.cleanup_gateway_e2e_orphan_traces() to service_role;